export function game2048Leaders(entries){const members=new Map();for(const row of Array.isArray(entries)?entries:[]){if(!row||typeof row.userId!=='string'||!row.userId||typeof row.name!=='string'||!row.name.trim()||!Number.isSafeInteger(row.score)||row.score<=0||!validTile(row.maxTile)||!Number.isFinite(row.at)||row.at<0||row.at>8640000000000000)continue;const previous=members.get(row.userId);if(!previous||row.score>previous.score||row.score===previous.score&&row.at<previous.at)members.set(row.userId,row);}return[...members.values()].sort((a,b)=>b.score-a.score||a.at-b.at||a.userId.localeCompare(b.userId)).slice(0,30);}
